# This file is generated by Flutter to redirect to the actual podhelper in the SDK.
# It uses the FLUTTER_ROOT environment variable or reads Generated.xcconfig.

def flutter_root
  # 1. Try environment variable (useful in CI/CD like GitHub Actions)
  if ENV['FLUTTER_ROOT'] && Dir.exist?(ENV['FLUTTER_ROOT'])
    return ENV['FLUTTER_ROOT']
  end

  # 2. Try Generated.xcconfig
  generated_xcode_build_settings_path = File.expand_path(File.join('..', 'Generated.xcconfig'), __FILE__)
  if File.exist?(generated_xcode_build_settings_path)
    File.foreach(generated_xcode_build_settings_path) do |line|
      matches = line.match(/FLUTTER_ROOT=(.*)/)
      return matches[1].strip if matches
    end
  end

  # 3. Fallback/Raise error
  raise "FLUTTER_ROOT environment variable not set, and Generated.xcconfig not found at #{generated_xcode_build_settings_path}"
end

require File.expand_path(File.join('packages', 'flutter_tools', 'bin', 'podhelper'), flutter_root)
